pragma solidity ^0.8.19;

// string constant ERR_INIT_CONTRACT = "PK:init";

string constant ERR_INCORRECT_SIBLINGS_SIZE = "PK:E02";

string constant ERR_TREE_LOCK_ALREADY_UPDATED = "PK:E05";
